package com.etpms;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;
public class AuthFilter implements Filter {public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse s=(HttpServletResponse)res;String path=r.getServletPath();if(path.equals("/login")||path.equals("/assets")||path.startsWith("/assets/")){chain.doFilter(req,res);return;}HttpSession session=r.getSession(false);if(session==null||session.getAttribute("user")==null){s.sendRedirect(r.getContextPath()+"/login");return;}if(path.startsWith("/admin")&&!"ADMIN".equals(session.getAttribute("role"))||path.startsWith("/manager")&&!java.util.Set.of("ADMIN","MANAGER").contains(session.getAttribute("role"))||path.startsWith("/employee")&&!java.util.Set.of("ADMIN","MANAGER","EMPLOYEE").contains(session.getAttribute("role"))){s.sendError(403,"You do not have permission to view this page.");return;}chain.doFilter(req,res);}}
